/**
 * @gp/data - card, island, worker and rules data, and the tuning
 * overlay the simulator varies it through.
 *
 * Platform-free, like the engine: the JSON is imported, never read from disk, so
 * the browser and Node get the same bytes with no loader to keep in sync.
 *
 * The split into four files follows PROVENANCE, not convenience:
 *
 *   cards.json      generated by tools/extract_cards.py from the sheet. Never
 *                   hand-edited: an edit here is overwritten by the next extract.
 *   island.json     authored, from the sheet's map tab plus the rulebook tables.
 *   workers.json    authored. Deliberately in no sheet - the sheet's components
 *                   tab is stale material from an older edition.
 *   rules.json      authored. The numbers that belong to no single card.
 *
 * Every file declares `meta.kind`, so "may I edit this by hand" is answerable
 * from the file itself.
 */

import cardsJson from '../data/cards.json' with { type: 'json' };
import islandJson from '../data/island.json' with { type: 'json' };
import workersJson from '../data/workers.json' with { type: 'json' };
import rulesJson from '../data/rules.json' with { type: 'json' };

import { deepFreeze } from './paths.js';
import { applyOverlay } from './overlay.js';
import type { Overlay } from './overlay.js';
import type {
  CardsFile,
  DoorAction,
  GameData,
  IslandFile,
  MeepleSpendTiming,
  RulesFile,
  Suit,
  WorkersFile,
} from './types.js';

export * from './types.js';
export { flatten, getPath, setPath, cloneData, deepFreeze } from './paths.js';
export type { Leaf } from './paths.js';
export { KNOB_TEMPLATES, listKnobs, deadTemplates } from './knobs.js';
export type { Knob, KnobTemplate, KnobType } from './knobs.js';
export {
  OVERLAY_SCHEMA_VERSION,
  OverlayError,
  DEFAULT_MAX_SWEEP_CELLS,
  validateOverlay,
  applyOverlay,
  expandSweep,
} from './overlay.js';
export type { Overlay, SweepAxis, SweepCell, SweepFile } from './overlay.js';

/**
 * ⛔ `serviceCardId` and `withServices` are GONE (change 6, 20/08/2026), and so
 * is the last of the vocabulary around them (v31, 02/09/2026).
 *
 * They synthesised five SERVICE starter cards out of `workers.json` - a fourth
 * starter per seat that a rival could place a card on to buy the suit's action.
 * Change 6 merged that door into the NOTICE BOARD, which is a real card in the
 * extract and always was, so there is nothing left to synthesise:
 * `data.cards.catalogue` is exactly the 105 rows of the sheet.
 *
 * Where the pieces went:
 *
 * - the door's THRESHOLD is `rules.economy.noticeBoardThreshold`, an override of
 *   the Notice Board's own printed value. `workers.serviceThreshold` is deleted:
 *   one number in two files is exactly how the old 5-versus-2 drift happened.
 *   ⚠️ OVERRIDE AND PRINT AGREED FROM v31 UNTIL 10/09/2026 AND DO NOT NOW: the
 *   override is 3 (S8's `3+`) and the sheet still prints 2 until
 *   `Isle-of-Farms-v36.xlsm`. The face is what has to catch up, and the v31
 *   control pins 2 so its own game is unchanged.
 * - `workers.roster` SURVIVES and is now read by TWO consumers, not one: a suit's
 *   Notice Board grants its action to a visitor, and a MEEPLE of that colour
 *   performs the same action free when spent. It stopped describing a card; it
 *   never stopped describing behaviour.
 * - `ownerActivationCost` and `visitWage` are deleted with the currency. In v31
 *   the owner places a card on their own board exactly as a rival does.
 */

/**
 * The committed numbers, with no overlay applied. Frozen: a caller that mutates
 * shared data would turn a balance run into a mystery, so the freeze converts
 * that into an exception at the point of the write.
 */
export const BASE_GAME_DATA: GameData = deepFreeze({
  cards: cardsJson as unknown as CardsFile,
  island: islandJson as unknown as IslandFile,
  workers: workersJson as unknown as WorkersFile,
  rules: rulesJson as unknown as RulesFile,
});

/**
 * The data a game or a simulation run reads.
 *
 * With no overlay this is `BASE_GAME_DATA` itself. With one, it is a fresh tree
 * with the overlay's leaves replaced, validated first: an unknown path, a path
 * the current extract no longer has, a type mismatch or a schema mismatch all
 * throw rather than silently doing nothing.
 */
export function loadGameData(overlay?: Overlay): GameData {
  if (!overlay) return BASE_GAME_DATA;
  return deepFreeze(applyOverlay(BASE_GAME_DATA, overlay));
}

/**
 * The DOOR a suit owns: the action its Notice Board grants, which is also the
 * action a meeple of that colour performs. Undefined if that suit has none,
 * which cannot happen in the shipped data and is asserted in `data.test.ts`.
 */
export function doorForSuit(data: GameData, suit: string) {
  return data.workers.roster.find((w) => w.linkedSuit === suit);
}

/** @deprecated The Services are gone (v31). Use `doorForSuit`. */
export const serviceForSuit = doorForSuit;

/**
 * The action a meeple of this colour performs when spent. Identical to the
 * suit's door by rule, and routed through one function so that stays true: a
 * meeple of a suit NOT at the table still works, so this must never be gated on
 * whether anybody owns that Notice Board.
 */
export function meepleAction(data: GameData, colour: string) {
  return doorForSuit(data, colour)?.action;
}

/**
 * ⭐ WHAT A SUIT'S DOOR BUYS IN THE GAME CURRENTLY LOADED. Since the commons
 * (and its Apiary GROW override) was deleted on 13/09/2026 this is always
 * `door.action`.
 *
 * One function, so "which action is this door" is answered in one spelling
 * across the engine, the bots and the sim, exactly as `meepleAction` did for the
 * meeple. Anything that DISPATCHES on a door's action must come through here;
 * anything that enumerates the five suit doors as a set may keep reading
 * `door.action`, because the set is the same five boards either way.
 *
 * Undefined if that suit has no door, which cannot happen in the shipped data.
 */
export function doorActionForSuit(data: GameData, suit: string): DoorAction | undefined {
  const door = doorForSuit(data, suit);
  if (!door) return undefined;
  return door.action;
}

/** Island tiles in play at this seat count (6 / 9 / 12). */
export function tilesInPlayCount(data: GameData, seats: number): number {
  const rows = data.island.slotsBySeats[String(seats)];
  if (!rows) return 0;
  return Object.values(rows).reduce((n, count) => n + count, 0);
}

/**
 * ⭐ THE TOKEN ISLAND'S SEAT SCALING (16/09/2026): how many tokens the pool
 * holds at this seat count. One per crop in play (the decks in play) per VP
 * value, plus the wild tokens. `data.test.ts` asserts it equals the tokens the
 * tiles hold.
 */
export function tokenPoolSize(data: GameData, seats: number): number {
  const crops = data.island.decksInPlayBySeats[String(seats)] ?? seats + 1;
  return crops * data.island.tokens.vpValues.length + wildTokensAt(data, seats);
}

/** Wild tokens in the pool at this seat count (0 / 2 / 4). */
export function wildTokensAt(data: GameData, seats: number): number {
  return data.island.tokens.wildBySeats[String(seats)] ?? 0;
}

/**
 * Does a token of this VP value carry a WORKER (the delivery meeple)? Printed
 * on the 3 and 4 VP tokens; `island.tokens.workerOnVp` `[]` seeds none.
 */
export function tokenCarriesWorker(data: GameData, vp: number): boolean {
  return data.island.tokens.workerOnVp.includes(vp);
}

/**
 * Is the MEEPLE-LOOP ARM on? One predicate, so that "which game are we playing"
 * is asked in exactly one spelling across the engine, the bots and the sim.
 *
 * Everything it gates: the visit's currency, the Notice Board being a building
 * at all, the bonus slot's second option, the turn-start meeple spend, the
 * supply cap and which island spaces carry a meeple.
 *
 * ⭐ IT DEFAULTS FALSE AGAIN SINCE 09/09/2026, WHEN DEAN RULED THE COMMONS IN.
 * It was written as an arm predicate with `'card'` as the shipped game, was the
 * shipped game itself from 04/09 to 09/09/2026, and is now one of TWO controls -
 * `overlays/meeple-loop-v1.overlay.json` for the v1 loop and
 * `overlays/meeple-economy-v1.overlay.json` for the reference-v14 game.
 *
 * ⛔ NEITHER THIS BRANCH NOR THE `'card'` ONE IS DEAD CODE, and neither may be
 * tidied away: they are the baselines every future delta is read against, and
 * the only things exercising them at scale are those overlays. ⚠️ AND A FALSE
 * HERE NO LONGER MEANS "the v31 game" - it means "not the meeple game", which
 * under the shipped default is the notice-board visit. Ask `isNoticeBoardPower` when the question is
 * which game, and this only when the question is meeples.
 */
export function isMeepleCurrency(data: GameData): boolean {
  return data.rules.turn.visitCurrency === 'meeple';
}

/**
 * Is the NOTICE BOARD VISIT live - the arm of 10/09/2026
 * (`docs/notice-board-visit-handoff-2026-09-10-v2.md`, S1-S16)? Under it the
 * centre is deleted, the five Notice Board cards go home to their owners' farms
 * and are BUILDINGS again, and the bonus (still taken FIRST) is to play one card
 * from your hand onto ANY player's Notice Board, your own included, and take
 * that board's PRINTED POWER. The card rests on the host's board until the host
 * harvests it into their barn, which is the host's whole payment.
 *
 * ⛔ IT IS A FOURTH CURRENCY AND NOT A REPOINTING OF `'card'`. The v31 control
 * carries three passengers this design does not want - a blocking board at 2,
 * the standalone free Draw 1, and the turn-start meeple spend - and one of the
 * three named controls may never move under an arm it is read against.
 *
 * One predicate, in one spelling, exactly as `isMeepleCurrency`
 * are: everything gated on which game this is asks one of the three and never
 * compares the raw string.
 */
export function isNoticeBoardPower(data: GameData): boolean {
  return data.rules.turn.visitCurrency === 'noticeBoardPower';
}

/**
 * Does a Notice Board CLOG at its threshold, or is the threshold only a minimum
 * to harvest at (S8, Dean 10/09/2026)?
 *
 * `false` is the shipped value and the `3+` rule: the board is harvestable at or
 * above `rules.economy.noticeBoardThreshold` and still accepts cards for ever.
 * `true` is the paired control that makes it an ordinary clogging building.
 *
 * ⛔ IT IS THE SEAM WHERE `isFull` AND `canTakeCard` STOP BEING THE SAME
 * QUESTION, which they have been everywhere in this codebase until now. A board
 * at five cards is harvestable AND still takes another; a caller that asks
 * "is it full" when it means "may I place here" will be wrong under the shipped
 * value and right under the control, which is the worst way round.
 *
 * ⚠️ Read only under `isNoticeBoardPower`: no other game has an owned Notice
 * Board with a threshold on it.
 */
export function noticeBoardBlocks(data: GameData): boolean {
  return data.rules.economy.noticeBoardBlocks;
}

/**
 * How many Notice Boards each player lays out at this seat count (Dean's
 * two-board fix, ruled 11/09/2026). One accessor, so "how many boards has a
 * seat got" is asked in exactly one spelling across the engine, the bots and the
 * sim, exactly as `meeplesDealt` reads `island.slotsBySeats`.
 *
 * Shipped at 2 at two seats and 1 otherwise since 13/09/2026. The arm set 2
 * at two seats only: a player's own suit's board, plus one more drawn AT RANDOM
 * from the suits nobody is farming, with the fifth board unused. At three and
 * four seats the arm is its own control, so those columns must reproduce
 * `overlays/notice-board-visit-no-self-v1.overlay.json` on identical seeds and
 * any difference there is a leak rather than a finding.
 *
 * ⭐ EVERY BOARD IT ADDS BELONGS TO A PERSON, which is the difference between
 * this and the deleted central-boards variant: targets go 2 / 2 / 3 by seat count and
 * every one of them pays its owner, so the hook is not diluted.
 *
 * ⛔ READ ONLY UNDER `isNoticeBoardPower` with `rules.turn.selfVisitAllowed`
 * false: no other game in this codebase has an owned Notice Board to duplicate.
 *
 * ⚠️ THE CEILING IS ARITHMETIC AND THIS FUNCTION DOES NOT ENFORCE IT. The suits
 * nobody is farming number `5 - seats`, so `n` boards each is realisable only
 * where `seats * (n - 1) <= 5 - seats`: 2 at two seats, 1 at three and four. An
 * overlay may ask for more, because the knob is a free map; what to do about an
 * infeasible value is an ENGINE ruling and it has not been made.
 *
 * Falls back to 1 for a seat count the map does not name, which is the shipped
 * rule rather than a guess.
 */
export function noticeBoardsPerSeat(data: GameData, seats: number): number {
  return data.rules.economy.noticeBoardsBySeats[String(seats)] ?? 1;
}

/**
 * How many cards the OWNER of a Notice Board draws when somebody else visits it
 * (S17, Dean, ruled 11/09/2026). One accessor, so "what does a host get" is asked
 * in exactly one spelling across the engine, the bots and the sim.
 *
 * Shipped at 0, which is the game as built and the rule as S7 wrote it: the card
 * the visitor pays rests on the board until its owner harvests it, and that is
 * the payment and there is no other. 1 is
 * `overlays/notice-board-visit-host-draw-v1.overlay.json`, where the host is
 * ALSO paid instantly, in a card off a deck.
 *
 * ⭐ ITS PROVENANCE IS A TABLE RATHER THAN A SIMULATION. Dean played
 * `overlays/notice-board-visit-two-boards-v1.overlay.json` at a two-player table
 * on 11/09/2026, house-ruled this in mid-session, and reported that it *"led to
 * a lot of extra cards in play, which relieved the tightness of the game in a
 * useful way"*. See `rules.turn.hostDrawOnVisit` for the amendment to S7 and for
 * the lens argument.
 *
 * ⛔ READ ONLY UNDER `isNoticeBoardPower`, exactly as `noticeBoardBlocks` and
 * `noticeBoardsPerSeat` are: no other game in this codebase has a host at all.
 * Under the commons a board belongs to nobody, so there is nobody to pay.
 *
 * ⛔ AND A SELF-VISIT MUST NEVER PAY IT. This function says how much a host
 * draws; it is the CALLER's job never to ask it about a visitor visiting
 * themselves. `turn.selfVisitAllowed` is false on the arm that matters, so the
 * case has no subject there, but a card drawn for visiting yourself is a pure
 * faucet paid by nobody and it must not be reachable.
 *
 * ⚠️ EVERY VISIT PAID THIS WAY ADDS A CARD TO THE GAME - about 14.4 visits
 * received per player per game at two seats under the control arm - and the
 * simulator cannot measure the effect Dean liked, because the engine's hand
 * limit of 7 is an instrument bound (C7) and the table plays with none.
 */
export function hostDrawOnVisit(data: GameData): number {
  return data.rules.turn.hostDrawOnVisit;
}

/**
 * ⭐ IS THE HOST-DRAW CAP ON - is a host paid AT MOST ONCE between their own
 * turns, however many neighbours visit them in the meantime?
 * (`rules.turn.hostDrawCapPerRound`, shipped `false`.)
 *
 * ⛔ **"PER ROUND" IS THE HOST'S OWN TURN CYCLE AND NOT THE VISITOR'S TURN.**
 * A cap on the visitor's turn would bite only when one visitor sends two visits
 * to the same host in one turn, which is reachable at two seats alone, and four
 * seats is the only seat count that breaches the band. The latch therefore lives
 * on the SEAT (`PlayerState.hostDrewThisRound`) and is cleared when that seat's
 * own turn begins, not on `TurnState`, which turn end replaces wholesale.
 *
 * ⚠️ It is a SECOND leaf and never a re-pointing of `hostDrawOnVisit`, which
 * keeps meaning cards per payment. See the knob's own description for why.
 */
export function hostDrawCapPerRound(data: GameData): boolean {
  return data.rules.turn.hostDrawCapPerRound;
}

/**
 * ⭐ HOW MANY CARDS A HOST DRAWS AT THIS SEAT COUNT, AND THIS IS THE ONE
 * SPELLING EVERY RULE MUST ASK IN (the engine, the bots and the sim alike).
 *
 * ⛔ **THE PRECEDENCE RULE, WRITTEN ONCE AND NOWHERE ELSE: A NON-NULL SLOT IN
 * `hostDrawOnVisitBySeats` WINS; A NULL SLOT DEFERS TO THE SCALAR
 * `hostDrawOnVisit`; AN ABSENT SEAT COUNT DEFERS TO THE SCALAR TOO.** Every slot
 * ships null, so the map changes nothing until somebody sets one, and
 * `overlays/notice-board-visit-host-draw-v1.overlay.json` - which sets the
 * scalar and no slot - still pays 1 at every seat count exactly as it did when
 * it was measured.
 *
 * ⛔ **`hostDrawOnVisit` IS THE BASE AND IS NOT THE ANSWER.** A rule that reads
 * the scalar directly is asking "what does the map say" with the map switched
 * off, which is right until the day somebody sets a slot and then silently
 * wrong. The scalar accessor is kept because the base value is a real thing to
 * read - a knob description, a report header - but **no branch of play may read
 * it.**
 *
 * ⚠️ Its reason for existing is in the knob's own description: capping the
 * faucet was measured on 11/09/2026 and failed, because the bonus rate is nearly
 * insensitive to the faucet's SIZE. Turning it off where there is no headroom is
 * what is left.
 */
export function hostDrawOnVisitAt(data: GameData, seats: number): number {
  return data.rules.turn.hostDrawOnVisitBySeats[String(seats)] ?? data.rules.turn.hostDrawOnVisit;
}

/**
 * ⭐ Is the own-crop end-game scorer printed on the BARN rather than the
 * Farmstead (Dean, 13/09/2026)? See the note on the type. Score-neutral.
 */
export function cropScorerOnBarn(data: GameData): boolean {
  return data.rules.economy.cropScorerOnBarn;
}

/**
 * Is R15 live - a meeple spendable as a card of its colour? See
 * `rules.turn.meepleAsCard`.
 *
 * ⭐ DEFAULTS FALSE. The knob is meaningless outside the meeple loop, but this
 * does not gate on `isMeepleCurrency` itself - the data can never set
 * `meepleAsCard` true while `visitCurrency` is `'card'` in practice, because
 * only handoff-v2 overlays touch it and they all set `visitCurrency: 'meeple'`
 * in the same breath. Callers that already know they are in the meeple arm may
 * read this directly; callers that do not should check `isMeepleCurrency`
 * first.
 */
export function isMeepleAsCard(data: GameData): boolean {
  return data.rules.turn.meepleAsCard;
}

/**
 * The amended R6 slot price, or null for the v1 block. See
 * `rules.turn.slotToll`.
 *
 * null: a slot holding any meeple is BLOCKED and refuses that colour outright.
 * A number n: nothing is ever refused, and visiting a slot already holding k
 * meeples costs n * k extra meeples of any colours - the toll - on top of the
 * acting meeple, boxed rather than handed to the host.
 */
export function slotTollOf(data: GameData): number | null {
  return data.rules.turn.slotToll;
}

/**
 * ⭐ R17: does a meeple spent as a CARD land on a neighbour's board rather
 * than in the box? Only ever true when `meepleAsCard` is on as well - there is
 * nothing to place when a meeple cannot pay for anything.
 */
export function meepleAsCardGoesToBoard(data: GameData): boolean {
  return data.rules.turn.meepleAsCard && data.rules.turn.meepleAsCardGoesTo === 'board';
}

/** The FLAT toll for placing a paid meeple onto an occupied slot (R17). */
export function paymentSlotTollOf(data: GameData): number {
  return data.rules.turn.paymentSlotToll;
}

/**
 * ⭐ The Dairy board's discount (Dean, ruling R10, 16/09/2026): *"Build,
 * spending cards of any crops, with a discount of 2."* Shipped 2.
 */
export function dairyDiscount(data: GameData): number {
  return data.rules.economy.noticeBoardPower.dairyDiscount;
}

/**
 * ⭐ The Vegetable board's relaxation (Dean, ruling R9, 16/09/2026): how many of
 * the delivery's cards may be of any crop. Shipped 2.
 */
export function vegetableWildCards(data: GameData): number {
  return data.rules.economy.noticeBoardPower.vegetableWildCards;
}

/**
 * ⭐ Which power the Apiary Notice Board prints (Dean's retext, ruled 14/09/2026).
 * Shipped 'deckGrowWild'. Read only under visitCurrency 'noticeBoardPower'.
 */
export function wheatHarvestGate(data: GameData): 'loaded' | 'nearFull' | 'full' {
  return data.rules.economy.noticeBoardPower.wheatHarvestGate;
}

export function apiaryPower(data: GameData): 'sow' | 'deckGrow' | 'deckGrowWild' {
  return data.rules.economy.noticeBoardPower.apiaryPower;
}

/**
 * ⭐ WHEN A HELD MEEPLE MAY BE SPENT (M4, Dean 12/09/2026, A151). One accessor,
 * so "which phase is the meeple spend" is asked in one spelling.
 *
 * ⛔ **`'start'` IS THE SHIPPED VALUE AND IT IS THE CURRENT BEHAVIOUR, NOT AN
 * OFF SWITCH.** The v31 control spends meeples at the start of the turn
 * (`meepleOptions` in the engine, and `turnflow.ts`'s own header) and
 * `packages/sim/fixtures/2p-v31-opening.json` replays against it, so `'none'`
 * would delete a live phase rather than change nothing. `'afterAction'` is M4's
 * arm: the spend moves to after the main action, the meeple buys the PLAIN
 * action of its colour, and it then leaves the game.
 */
export function meepleSpendTiming(data: GameData): MeepleSpendTiming {
  return data.rules.turn.meepleSpendTiming;
}

/**
 * ⭐ HOW MANY MEEPLES ONE SEAT MAY SPEND IN A TURN (M5, Dean 12/09/2026, A151),
 * or `null` for UNLIMITED, which is the shipped value and the game as it plays
 * today.
 *
 * ⛔ **`null` IS "NO RULE HERE" AND `0` WOULD BE "NO SPEND AT ALL".** That is the
 * established idiom of `commonsThreshold`, `commonsHarvestTake` and
 * `meepleCapPerColour`, and it is why this ships null rather than the 0 the
 * build handoff's table asked for: there is no per-turn cap in the game today,
 * so 0 would delete the v31 control's phase.
 *
 * ⚠️ The arm is 1, which is Dean's ruling, and C112 asks for it to be run
 * against `meepleSpendDistinctColours` instead. The two are orthogonal leaves.
 */
export function meepleSpendPerTurn(data: GameData): number | null {
  return data.rules.turn.meepleSpendPerTurn;
}

/**
 * ⭐ C112'S ALTERNATIVE TO THE PER-TURN CAP: may no two meeples spent in one
 * turn share a colour? Shipped `false`, which is inert because no such
 * restriction exists today.
 *
 * ⛔ A SECOND LEAF RATHER THAN A MAGIC VALUE OF `meepleSpendPerTurn`, because
 * "no two of the same colour" is not expressible as an integer and because
 * re-pointing a published quantity at a rule of a different shape is a mistake
 * this project has paid for twice (a17 on 09/09/2026, the meeple cap on
 * 05/09/2026). `meepleSpendPerTurn` keeps meaning HOW MANY; this says WHICH ONES
 * MAY BE COMBINED.
 *
 * ⚠️ The two arms C112 wants are one run apart: the rule as ruled is
 * `meepleSpendPerTurn` 1 with this false, and the variant is
 * `meepleSpendPerTurn` null with this true. The cap of 1 removes exactly the
 * combo burst Dean's own table enjoyed on 11/09/2026, which is why the
 * alternative has to be measured rather than argued.
 */
export function meepleSpendDistinctColours(data: GameData): boolean {
  return data.rules.turn.meepleSpendDistinctColours;
}

/** Cards actually in the game: the enable flag applied. */
export function activeCards(data: GameData = BASE_GAME_DATA) {
  return data.cards.catalogue.filter((card) => card.enabled);
}

/**
 * ⭐ THE DELIVERY COST: always tokens-per-tile x cards-per-token = 4 barn cards
 * (the token island, 16/09/2026). A first delivery pays both tokens' demands; a
 * second pays the last token's demand plus the rest in cards of ANY crops.
 */
export function deliveryCost(data: GameData): number {
  const { crates, cardsPerCrate } = data.island.tileRule;
  return crates * cardsPerCrate;
}

/** Tokens dealt onto a tile at setup (2). */
export function tokensPerTile(data: GameData): number {
  return data.island.tileRule.crates;
}

/** Cards one token's demand asks for (2). */
export function cardsPerToken(data: GameData): number {
  return data.island.tileRule.cardsPerCrate;
}

/**
 * One island token, structurally, so an engine `IslandToken` and a view token
 * both fit without this package knowing either. `demand` is a crop, or `'wild'`
 * for a token that takes any cards; `worker` is the Worker's colour, or null.
 */
export interface TokenRecord {
  readonly demand: Suit | 'wild';
  readonly vp: number;
  readonly worker: Suit | null;
}

/**
 * ⭐ WHAT A DELIVERY TO A TILE HOLDING THESE TOKENS MUST PAY, AND THE ONE
 * SPELLING OF THE PAYMENT RULE (16/09/2026). `base` is the named crops, one
 * token's worth of cards per crop token; `any` is the rest of the delivery cost
 * in cards of any crops: the wild tokens' cards, plus, on a tile that has lost a
 * token already, the revealed "2 any". The total is always `deliveryCost`, so a
 * first delivery pays pair + pair and a second pays pair + 2 any. A delivery
 * that takes BOTH tokens (V14) pays exactly the same as one that takes one.
 */
export function tileDemand(
  data: GameData,
  tokens: readonly TokenRecord[],
): { base: Partial<Record<Suit, number>>; any: number } {
  const per = cardsPerToken(data);
  const base: Partial<Record<Suit, number>> = {};
  let named = 0;
  for (const token of tokens) {
    if (token.demand === 'wild') continue;
    base[token.demand] = (base[token.demand] ?? 0) + per;
    named += per;
  }
  return { base, any: Math.max(0, deliveryCost(data) - named) };
}

/**
 * How many of a payment's cards miss the named demand: the sum over crops of
 * what `base` asks for and `spend` does not supply. 0 is an exact payment; the
 * Vegetable board accepts up to `vegetableWildCards`.
 */
export function demandShortfall(
  base: Partial<Record<Suit, number>>,
  spend: Partial<Record<Suit, number>>,
): number {
  let short = 0;
  for (const [suit, want] of Object.entries(base) as [Suit, number][]) {
    short += Math.max(0, want - (spend[suit] ?? 0));
  }
  return short;
}
